```python
from fractions import Fraction, gcd

def get_fraction_input():
    """Get user input for two fractions."""
    while True:
        try:
            numerator1 = float(input("Enter the numerator of the first fraction: "))
            denominator1 = float(input("Enter the denominator of the first fraction: "))
            fraction1 = Fraction(numerator1, denominator1)

            numerator2 = float(input("Enter the numerator of the second fraction: "))
            denominator2 = float(input("Enter the denominator of the second fraction: "))
            fraction2 = Fraction(numerator2, denominator2)

            return fraction1, fraction2
        except ValueError:
            print("Invalid input. Please enter numbers for the numerator and denominator.")

def perform_operation(fraction1, fraction2, operation):
    """Perform the given operation on two fractions and return the result."""
    if operation == '+':
        return fraction1 + fraction2
    elif operation == '-':
        return fraction1 - fraction2
    elif operation == '*':
        return fraction1 * fraction2
    elif operation == '/':
        return fraction1 / fraction2
    else:
        raise ValueError("Invalid operation. Choose from +, -, *, or /.")

def simplify_fraction(fraction):
    """Simplify a fraction by finding the greatest common divisor (GCD)."""
    g = gcd(fraction.numerator, fraction.denominator)
    return Fraction(fraction.numerator // g, fraction.denominator // g)

def main():
    fraction1, fraction2 = get_fraction_input()
    operation = input("Enter the operation (+, -, *, or /): ").strip()

    result = perform_operation(fraction1, fraction2, operation)
    result = simplify_fraction(result)

    print(f"{fraction1} {operation} {fraction2} = {result}")

if __name__ == "__main__":
    main()
```

This program will prompt the user to enter the numerator and denominator of two fractions, and then allow them to choose the operation to perform. The result will be a simplified fraction.
